const express = require('express');
const app = express();

// Configuration A
app.use(express.json());

// Configuration B
app.use(express.json({ limit: '10kb' }));

app.use((err, req, res, next) => {
  res.status(500).json({
    error: err.message,
    stack: process.env.NODE_ENV === 'production' ? null : err.stack
  });
});

const cors = require('cors');

app.use(cors({
  origin: '*',
  credentials: true
}));
